raw:
{
  "spells": [
    {
      "id": "spell_fire_10",
      "theory": "炉膛鼓焰以树脂为引，将魔力沿着炉壁的旧裂纹与铁架缝隙送入火焰根部，使炭火与柴薪之间的燃烧更充分。它只提高现有炉火的温度，不代替燃料，也不点燃未接触火焰的物件。铁匠炉、陶窑和旅店灶台都可接受这种助燃，但炉膛若已有裂缝，热力会从裂缝外泄，反而使火舌偏向一侧。",
      "casting": "取一小块树脂点在炉门边，用火钳轻敲炉壁三下，再以手掌压住炉门中央送入魔力，直到火焰由红转白。",
      "failure": "树脂受热后只冒浓烟而不助燃，炉温短暂下降，随后火焰从炉门缝隙窜出，在炉前留下焦痕。若炉壁已有暗裂，可能听见闷响，裂缝扩大，但不会炸开整个炉体。",
      "counters": [
        "向炉膛撒湿沙或泼少量水，可迅速压低火焰温度。",
        "关闭炉门风闸并移开树脂，火势会因缺氧而回到普通状态。"
      ],
      "socialConsequences": "铁匠与陶匠欢迎这种助燃，尤其在赶制订单时能节省燃料。卖炭和卖柴的人担心常客减少购买，但炉温提高后仍要投入正常燃料，因此生意不会断绝。旅店灶台若在用餐时使用，厨师须注意不使油烟倒灌；邻桌客人闻到焦味会要求退菜，责任由施术者与店主按乡约协商。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时火焰忽明忽暗，须反复添柴才能保持炉温。",
        "环线稳定后，炉温可均匀维持到预定火候。",
        "熟练者能按铁料厚度调整送魔节奏，减少燃料浪费。",
        "更高熟练度使火焰颜色稳定，温度仍限于原炉承受范围。"
      ]
    },
    {
      "id": "spell_fire_11",
      "theory": "隔焰罩用树脂在目标衣物外层织出一层极薄的热阻膜，使外来火焰的热量在触及皮肤前被偏转和分散。这层膜只削减火焰伤害，对刀剑、箭矢和钝击没有阻挡作用。罩子依附在受术者身上，若受术者剧烈翻滚，膜会从摩擦处剥落。潮湿衣物会削弱热阻，但不会让罩子完全失效。",
      "casting": "将树脂在掌心搓热，隔空对目标画一个半圆，同时低声念出短促音节，直到目标衣料表面泛起一层淡红光泽。",
      "failure": "半圆画歪时，热阻膜只覆盖目标半边身体，另一侧仍会被火焰灼伤。淡红光泽可能变成刺眼红斑，使目标误以为罩子更强而贸然靠近火源，结果遭受更重的烧伤。",
      "counters": [
        "用大量冷水浇透受术者，热阻膜会因水汽而暂时失效。",
        "以长杆武器挑开受术者外层衣物，膜随衣物脱落。"
      ],
      "socialConsequences": "救火队和炼金工坊的学徒愿意在靠近火源时接受此罩，尤其搬运热坩埚时能减少烫伤。卖防火斗篷的商人会抱怨生意被分走，但仍能出租重型防火服给需要深入火场的人。城中消防队要求施术者不得在拥挤街巷随意使用，以免淡红光泽引起恐慌；若罩子失效导致烧伤，责任由施术者与雇主按公会许可条款分担。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时隔焰罩常只覆盖胸背，四肢仍暴露在热浪中。",
        "熟练后能均匀覆盖全身，但潮湿处仍会先失效。",
        "掌握节奏者可在目标移动中补上剥落部位，减少灼伤。",
        "更高熟练度使淡红光泽更淡，仍不抵挡刀剑与重物。"
      ]
    },
    {
      "id": "spell_fire_12",
      "theory": "熔缝术以铁料为填充，将魔力集中在金属裂缝两侧，使铁料与母材在高温下局部熔合，冷却后填补缺口。它不能创造缺失的部件，也不能把铁变成钢。裂缝中的油污和锈迹会阻碍熔合，因此施术前须清理缝口。薄壁器皿受热后容易变形，厚铸件则需更长时间。",
      "casting": "把铁料碎块塞入裂缝，用指尖沿缝口画一道波浪线，再以铁锤轻敲三下，同时持续送入魔力直到铁料发亮。",
      "failure": "铁料只软化而不熔合，冷却后从裂缝中脱落，留下凹凸不平的焊疤。若魔力送入过快，薄壁处会烧穿，形成新的孔洞，使原本可修补的器皿彻底报废。",
      "counters": [
        "向熔缝处持续滴水，可阻止铁料与母材熔合。",
        "用湿布包裹裂缝周围，热量被导走，熔缝无法完成。"
      ],
      "socialConsequences": "铁匠和修补匠欢迎此术，尤其修补农具和船锚时能节省换新费用。卖新铁器的商人担心旧货修补后需求减少，但仍能向追求强度的客人出售整铸件。港口船主在修补货舱铁箍时须请港务验看，若修补处日后在航行中裂开导致货损，施术者与船主按港务规定共同承担赔偿。",
      "law": {
        "river": "consent",
        "city": "consent",
        "port": "consent"
      },
      "proficiencyEffects": [
        "初学时焊疤厚薄不均，冷却后常需再次返工。",
        "熟练后能控制熔合范围，减少母材变形。",
        "掌握火候者可在薄壁器皿上修补小缝而不烧穿。",
        "更高熟练度使焊口平整，强度仍不超过原铁料。"
      ]
    }
  ]
}
